@startuml

class Provider {
  + Name : string
  + Location : string
}

class Cruise {
  + CruiseNumber : int
  + Name : string
  + StartDate : date
  + EndDate : date
}

class Employee {
  + Name : string
  + Ssn : int
}

class Guest {
  + Name : string
  + VIP : boolean
}

class Ship {
  + Name : string
  + DeckCount : int
  + Length : float
  + PassengerCount : int
}

class TravelAgency {
  + Name : string
  + Address : string
}

class Booking {
  + BookingNumber : int
  + BookingDate : date
}

class Destination {
  + Name : string
  + Sea : string
}

class Show {
  + Title : string
  + Duration : int
}

class Ticket {
}

Provider "1" -- "*" Cruise : organizes
Cruise "*" -- "*" Employee : requires
Cruise "*" -- "*" Guest : guests take part in
Cruise "*" -- "0..*" Ship : uses
Cruise "1" -- "0..*" Booking : booked through
TravelAgency "1" -- "*" Booking : manages
Cruise "*" -- "1" Destination : heads for
Cruise "1" -- "*" Show : offers
Cruise "1" -- "*" Ticket : issues
Guest "1" -- "0..*" Ticket : has
Ticket "*" -- "1" Cruise : belongs to

@enduml

